//screen reso
var winwd = 0;
var winht = 0;
var tmpid;
var deleting = false;
// wx.cloud.init();

export default {
	data() {
		return {
			currentTab: 0,
			user_openId: 'AAA',
			shopid: "",
			imgPop: false,
			newImgStr: "",
			newAds: "",
			loopimgs1: "",
			loopadsHT: "",
			loopadsWD: "",
			scrollHeight: "",
			initCardPos: "",
			cardHeight: "",
			goods: "",
			cata: ""
		};
	},

	components: {},
	props: {},
	onReady: function() {},
	onPullDownRefresh: function() {
		wx.stopPullDownRefresh();
	},
	onLoad: function() {
		tmpid = wx.getStorageSync('shopid');
		console.log(tmpid);
		this.setData({
			shopid: tmpid
		}); //get user's screen reso

		wx.getSystemInfo({
			success: function(res) {
				winwd = res.windowWidth;
				winht = res.windowHeight;
			}
		});
		this.setData({
			//screen reso
			loopadsHT: winht * 0.3,
			loopadsWD: winwd,
			scrollHeight: winht * 0.64,
			initCardPos: winht * 0.36,
			cardHeight: winht * 0.64 * 0.6
		});
		var that = this;
		uni.request({
			url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getdatawithkey',
			method: 'POST',
			data: {
				dbname: "StoreAds",
				shopId: tmpid
			},
			success: function(res) {
				that.setData({
					loopimgs1: res.result.data[0].contents
				});
			}
		});
		uni.request({
			url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getdatawithkey',
			method: 'POST',
			data: {
				dbname: "items",
				shopId: tmpid
			},
			success: function(res) {
				that.setData({
					goods: res.result.data[0].contents
				});
			}
		});
		uni.request({
			url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getfromdb',
			method: 'POST',
			data: {
				mode: 1,
				target: "shops",
				iddd: tmpid
			},
			success: function(res) {
				wx.stopPullDownRefresh();
				console.log(res.data.Items[0].catagory);
				that.setData({
					cata: res.data.Items[0].catagory
				});
			},
			fail: function(res) {
				console.log(res);
			}
		});
	},
	onPullDownRefresh: function() {
		this.onLoad();
		console.log("call pulldown");
	},
	methods: {
		updateImg: function(e) {
			console.log(e.detail.value);
			this.setData({
				newImgStr: e.detail.value
			});
		},
		updateAds: function(e) {
			console.log(e.detail.value);
			this.setData({
				newAds: e.detail.value
			});
		},
		parseNewImg: function() {
			var img1 = this.newImgStr;
			var ads1 = this.newAds;
			var that = this;
			var shopId = tmpid;
			console.log(shopId);
			var newL = [{
				des: ads1,
				img: img1
			}];
			console.log(newL);
			uni.request({
				url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/postpost',
				method: 'POST',
				data: {
					mode: 3,
					sId: shopId,
					contents: newL
				},
				success: function(res) {
					console.log(res);
					that.setData({
						loopimgs1: newL,
						imgPop: false
					});
				},
				fail: function(res) {
					that.setData({
						imgPop: false
					});
				}
			});
		},
		cancelImg: function() {
			this.setData({
				imgPop: false
			});
		},
		openAds: function() {
			this.setData({
				imgPop: true
			});
		},
		clickTab: function(e) {
			var that = this;

			if (this.currentTab === e.target.dataset.current) {
				return false;
			} else {
				that.setData({
					currentTab: e.target.dataset.current
				});
			}

			console.log(this.currentTab);
		},
		stopTouchMove: function() {
			return false;
		},
		clickItem: function(e) {
			console.log(e.currentTarget.dataset.itemid);
			wx.setStorageSync("itemId", e.currentTarget.dataset.itemid);
			wx.setStorageSync("shopid", tmpid); //var tmp=wx.getStorageSync('shopid');

			wx.navigateTo({
				url: '../manageItem/manageItem'
			});
		},
		toAddPage: function() {
			wx.setStorageSync("shopid", this.shopid);
			wx.navigateTo({
				url: '../addItem/addItem'
			});
		},
		deletItem: function(e) {
			if (!deleting) {
				deleting = true;
				var that = this;
				console.log(e.currentTarget.dataset.itemid);
				var imid = e.currentTarget.dataset.itemid.itemId;
				var in1 = e.currentTarget.dataset.index1;
				var in2 = e.currentTarget.dataset.index2; //1. delete from items

				var tmpList = this.goods;
				var tmpList1 = tmpList[in1].splice(in2, 1);
				uni.request({
					url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/postpost',
					method: 'POST',
					data: {
						mode: 1,
						sid: that.sid,
						contents: tmpList
					},
					success: function(res) {
						console.log(res);
					},
					fail: function(res) {
						console.log(res);
						deleting = false;
					}
				}); //2. delete from iteminfo

				uni.request({
					url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/postpost',
					method: 'POST',
					data: {
						mode: 2,
						itemId: imid
					},
					success: function(res) {
						console.log(res);
						that.setData({
							goods: tmpList
						});
						deleting = false;
					},
					fail: function(res) {
						console.log(res);
						deleting = false;
					}
				});
				console.log(this.goods);
			}
		},
		setData: function(obj, callback) {
			let that = this;
			let keys = [];
			let val, data;
			Object.keys(obj).forEach(function(key) {
				keys = key.split('.');
				val = obj[key];
				data = that.$data;
				keys.forEach(function(key2, index) {
					if (index + 1 == keys.length) {
						that.$set(data, key2, val);
					} else {
						if (!data[key2]) {
							that.$set(data, key2, {});
						}
					}

					data = data[key2];
				});
			});
			callback && callback();
		}
	}
};
